from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)
def mk(amount="80.00", status="captured"):
    return Payment("pay_1","inv_1",Decimal(amount),status=status,created_at=T0,captured_at=T0)

# partial then full
p = mk()
outage_refund(p, Decimal("30.00"), T0)
print("partial:", p.refunded_amount, p.status)
outage_refund(p, Decimal("50.00"), T0)
print("full:", p.refunded_amount, p.status)

# validation
for amt in ("0", "-1"):
    try: outage_refund(mk(), Decimal(amt), T0)
    except BillingError as e: print("amt", amt, e.code)
try: outage_refund(mk(), Decimal("81.00"), T0)
except BillingError as e: print("exceed", e.code)
try: outage_refund(mk(status="authorized"), Decimal("1.00"), T0)
except BillingError as e: print("state", e.code)

# approval threshold (1000)
try: outage_refund(mk("2000.00"), Decimal("1000.01"), T0)
except BillingError as e: print("approval", e.code)
p = mk("2000.00"); outage_refund(p, Decimal("1000.00"), T0); print("at threshold ok:", p.refunded_amount)
p = mk("2000.00"); outage_refund(p, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok:", p.refunded_amount)

# idempotency
p = mk()
outage_refund(p, Decimal("10.00"), T0, idempotency_key="k1")
r = outage_refund(p, Decimal("10.00"), T0, idempotency_key="k1")
print("idem same:", r is p, p.refunded_amount)
print("audit entries:", len(audit.events("outage_refund")))
print("audit has key:", audit.events("outage_refund")[0]["idempotency_key"])
EOF"}

